-- ============================================================
-- PPWR Radar – Migration v1.2: Rollen-Engine (Schicht 1)
-- Ersetzt die leeren Platzhalter-Tabellen aus Schema v1.0 durch die
-- Struktur aus dem Rollen-Engine-Paket v0.91 (Chat 1), harmonisiert:
--  * review_status als System-Enum statt deutscher Textwerte
--  * RLS gemäß Freigabe-Prinzip (Chat-1-Vorschlag 'using(true)' hätte
--    Entwürfe öffentlich gemacht – korrigiert)
--  * 'veraltet' über Spalte aktiv statt Enum-Erweiterung
-- ============================================================

drop table if exists rollen_regeln;
drop table if exists rollen_definitionen;

create table rollen_definitionen (
  rolle_id                text primary key,
  typ                     text not null check (typ in ('kernrolle','sammelbegriff','hilfsbegriff')),
  begriff_de              text not null,
  begriff_en              text,
  fundstelle_ppwr         text not null,
  definition_kurz         text not null,
  funktion_im_system      text,
  alt_bedeutung_verpackg  text,
  abgrenzung              text,
  verwechslungsfaelle     text,
  verpackdg_bezug         text,
  leitfaden_bezug         text,
  status                  text,
  flag                    text,
  aktiv                   boolean not null default true,
  review_status           review_status not null default 'entwurf',
  rechtsstand             date not null,
  cattwyk_review_am       date
);

create table rollen_regeln (
  regel_id             text primary key,
  block                text not null check (block in ('erzeuger','hersteller','weitere','output')),
  prioritaet           int not null,
  wenn_bedingung       text not null,
  dann_rollen          text not null,
  geltungsebene        text,
  fundstelle_primaer   text not null,
  fundstelle_sekundaer text,
  erlaeuterung         text,
  input_variablen      text,
  flag                 text,
  aktiv                boolean not null default true,
  review_status        review_status not null default 'entwurf',
  rechtsstand          date not null default current_date,
  cattwyk_review_am    date
);

create table wizard_fragen (
  frage_id          text primary key,
  reihenfolge       int not null,
  ebene             text not null check (ebene in ('unternehmen','produktlinie')),
  frage_text        text not null,
  antwort_typ       text not null check (antwort_typ in ('single_select','multi_select','freitext_liste')),
  antwort_optionen  text,
  ziel_variable     text not null,
  bedingung_anzeige text,
  gespeiste_regeln  text,
  hinweis_ui        text
);

create table rollen_ergebnisse (
  id             uuid primary key default gen_random_uuid(),
  profil_id      uuid not null references profile(id) on delete cascade,
  produktlinie   text not null,
  rollen_set     jsonb not null,
  herleitung     jsonb not null,
  rechtsstand    date not null,
  engine_version text not null,
  erstellt_am    timestamptz not null default now()
);

alter table rollen_definitionen enable row level security;
alter table rollen_regeln       enable row level security;
alter table wizard_fragen       enable row level security;
alter table rollen_ergebnisse   enable row level security;

create policy "freigegebene rollen_definitionen" on rollen_definitionen
  for select to authenticated
  using (review_status = 'cattwyk_freigegeben' and aktiv);

create policy "freigegebene rollen_regeln" on rollen_regeln
  for select to authenticated
  using (review_status = 'cattwyk_freigegeben' and aktiv);

create policy "wizard_fragen lesen" on wizard_fragen
  for select to authenticated using (true);

create policy "eigene rollen_ergebnisse" on rollen_ergebnisse
  for select to authenticated
  using (profil_id in (select id from profile where user_id = auth.uid()));
-- Schreibzugriff überall nur via Service Role (Freigabe-/Engine-Workflow)


-- ---------- Daten-Import ----------

insert into rollen_definitionen (rolle_id, typ, begriff_de, begriff_en, fundstelle_ppwr, definition_kurz, funktion_im_system, alt_bedeutung_verpackg, abgrenzung, verwechslungsfaelle, verpackdg_bezug, leitfaden_bezug, status, flag, review_status, rechtsstand) values
('wirtschaftsakteur', 'sammelbegriff', 'Wirtschaftsakteur', 'economic operator', 'Art. 3 Abs. 1 Nr. 12 VO (EU) 2025/40', 'Sammelbegriff: der Erzeuger, der Lieferant, der Importeur, der Vertreiber, der Bevollmächtigte, der Endvertreiber und der Fulfillment-Dienstleister.', 'Adressat allgemeiner Pflichten (z. B. Verbote des Art. 25, Leerraum Art. 24, Wiederverwendungsziele Art. 29).', 'Kein Pendant im VerpackG; das VerpackG kannte nur Hersteller/Vertreiber/Letztvertreiber.', 'Der ''Hersteller'' (Nr. 15) ist in der Aufzählung NICHT genannt: Er ist keine eigenständige Akteursart, sondern eine Querschnittsrolle, die einem Erzeuger, Importeur oder Vertreiber zusätzlich zufällt.', 'Nutzer erwarten ''Hersteller'' in der Liste; das Fehlen ist gewollt und muss im UI erklärt werden.', '—', '—', 'in Kraft ab 12.08.2026', null, 'entwurf', '2026-07-17'),
('erzeuger', 'kernrolle', 'Erzeuger', 'manufacturer', 'Art. 3 Abs. 1 Nr. 13 lit. a und b VO (EU) 2025/40', 'Jede natürliche oder juristische Person, die Verpackungen oder ein verpacktes Produkt herstellt; lit. a: bei Fertigung unter eigenem Namen/eigener Marke ist Erzeuger, wer entwickeln oder herstellen lässt (Markenkriterium), unabhängig von weiteren sichtbaren Marken; lit. b: Kleinstunternehmen-Ausnahme – ist der Markeninhaber ein Kleinstunternehmen (Empfehlung 2003/361/EG, Stand 11.02.2025) und sitzt der Verpackungslieferant im selben Mitgliedstaat, gilt der Lieferant als Erzeuger.', 'Konformitätsverantwortung: darf nur Verpackungen in Verkehr bringen, die Art. 5–12 entsprechen (Art. 15 Abs. 1); Konformitätsbewertung (Art. 38), technische Dokumentation (Anhang VII), EU-Konformitätserklärung (Art. 39, Anhang VIII). EU-weit gibt es je Verpackung nur EINEN Erzeuger.', '''Erzeuger'' existierte im VerpackG nicht als Rolle. Die Konformitäts-/Produktverantwortung lag diffus bei dem, der Verpackungen in Verkehr brachte. ACHTUNG: Was die Branche bisher umgangssprachlich ''Hersteller der Verpackung'' nennt, ist in der PPWR der ''Erzeuger''.', 'Erzeuger = Produktkonformität (einmal EU-weit); Hersteller (Nr. 15) = erweiterte Herstellerverantwortung (je Mitgliedstaat). Bei Verkaufs-/Umverpackungen ist Erzeuger regelmäßig der Abfüller (letzter Verarbeitungsschritt: Zuschneiden, Befüllen, Versiegeln); bei Transport-, Service- und Primärproduktionsverpackungen regelmäßig der physische Verpackungshersteller, außer die Verpackung trägt die Marke des Nutzers. Ohne Marke entscheidet, wer bestellt und die Designspezifikationen festlegt.', '(1) Sprachfalle: DE ''Erzeuger'' = EN ''manufacturer'', DE ''Hersteller'' = EN ''producer'' – exakt invers zur Intuition und zur EN-Fachliteratur. (2) Eigenmarke: Der Händler mit Private Label wird Erzeuger, obwohl er nichts physisch produziert. (3) Importeur/Vertreiber wird via Art. 21 zum Erzeuger (Eigenmarke oder konformitätsrelevante Veränderung). (4) Kleinstunternehmen-Ausnahme verlagert die Rolle auf den Lieferanten – auch wenn dieser selbst kein Kleinstunternehmen ist.', 'Erzeuger als solcher wird im VerpackDG kaum adressiert (Konformität ist EU-Recht); Sprachregel für EU-Konformitätserklärungen: Deutsch ODER Englisch nach Wahl des Herstellers, Übersetzung ins Deutsche auf Behördenverlangen (§ 62 VerpackDG); Bußgeldtatbestände knüpfen an Erzeugerpflichten an (§ 66 VerpackDG).', 'Leitfaden C(2026)3702, Abschn. 2: nur ein Erzeuger je Lieferkette; Abfüller-Regel für Verkaufs-/Umverpackungen; Markenkriterium; Kleinstunternehmen-Rechenregeln inkl. Verbundunternehmen/Franchise.', 'in Kraft ab 12.08.2026', null, 'entwurf', '2026-07-17'),
('hersteller', 'kernrolle', 'Hersteller', 'producer', 'Art. 3 Abs. 1 Nr. 15 lit. a–e VO (EU) 2025/40', 'Jeder Erzeuger, Importeur oder Vertreiber, der – unabhängig von der Verkaufsmethode, auch im Fernabsatz – (a) Transport-, Service- oder Primärproduktionsverpackungen (leer, Einweg oder Mehrweg) erstmals im Sitz-Mitgliedstaat und von dort aus bereitstellt; (b) verpackte Produkte in sonstigen Verpackungen erstmals im Sitz-Mitgliedstaat und von dort aus bereitstellt; (c)/(d) dieselben Verpackungen bzw. verpackten Produkte aus einem anderen Mitgliedstaat oder Drittland erstmals direkt an Endabnehmer in einem anderen Mitgliedstaat bereitstellt; (e) verpackte Produkte auspackt, ohne Endabnehmer zu sein, sofern kein anderer Hersteller nach lit. a–d existiert (Auffangtatbestand).', 'Erweiterte Herstellerverantwortung (Art. 45 Abs. 1) im Mitgliedstaat, in dem die Verpackung voraussichtlich zu Abfall wird; Registrierung im Herstellerregister (Art. 44); in DE: Registrierung bei der ZSVR/LUCID (§ 6 VerpackDG), Systembeteiligung (§ 7 VerpackDG), Datenmeldung (§ 9), ggf. Vollständigkeitserklärung (§ 10), Rücknahmepflichten (§ 39). Je Mitgliedstaat genau ein Hersteller je Verpackungseinheit.', 'VerpackG § 3 Abs. 14: Hersteller = Erstinverkehrbringer; als Hersteller galt auch der Importeur. Nahe an PPWR lit. b (Abfüller-Fall), ABER neu: (1) Auspacker-Tatbestand lit. e, (2) Serviceverpackungen: Hersteller ist jetzt originär der erste Bereitsteller der LEEREN Serviceverpackung (Entlastung kleiner Befüller, ErwG 122) statt des Befüllers mit Delegationsoption, (3) explizite Fernabsatz-Tatbestände lit. c/d, (4) strikte Ein-Hersteller-je-Mitgliedstaat-Logik mit Gebührenerstattung bei Weitervertrieb in andere Mitgliedstaaten. (Alt-Recht redaktionell verifizieren.)', 'Hersteller ≠ Erzeuger: Ein Unternehmen kann beides sein (Marken-Abfüller in DE), nur eines oder keines. Bestimmung stets JE PRODUKTLINIE und JE MITGLIEDSTAAT. Export aus der EU: kein Hersteller (kein Abfall in der EU). Logistikunternehmen, die Drittlandsware aus- und umpacken, sind Hersteller der anfallenden Transportverpackung, auch ohne Eigentum (ErwG 123).', '(1) EN ''producer'' – Übersetzungsfalle s. Erzeuger. (2) ''Wir sind doch registriert'' – LUCID-Registrierung nach altem VerpackG gilt fort (§ 68 Abs. 2 VerpackDG), aber die ROLLENBESTIMMUNG folgt neuen Tatbeständen; neu Verpflichtete (z. B. Auspacker) müssen sich bis 12.09.2026 registrieren. (3) B2B-Auspacken: Wer verpackte Produkte für den Weitervertrieb auspackt, ist kein Endabnehmer und kann Hersteller nach lit. e sein.', '§ 5 (Bevollmächtigter), § 6 (Registrierung; ZSVR = zuständige Behörde für das Register nach Art. 44 Abs. 1, § 6 Abs. 6), § 7 (Systembeteiligung; Übertragung bei Serviceverpackungen auf Vorvertreiber § 7 Abs. 2), § 9 (Datenmeldung), § 10 (Vollständigkeitserklärung), § 39 (Rücknahme nicht systembeteiligungspflichtiger Verpackungen), § 68 (Übergangsrecht: Fortgeltung Systembeteiligungen längstens bis 31.12.2026, Registrierungs-Fortgeltung, Fristen 12.09./12.11.2026).', 'Leitfaden C(2026)3702, Abschn. 3: Entscheidungsbaum; Abfüller-Regel für Verkaufsverpackungen; Transportverpackungs-Prüfschritte; Fernabsatz; Logistiker; Gebührenerstattung. EUNR-Papier 06/2026 (Sekundärquelle): ''domestic priority'', Beginn der inländischen Lieferkette.', 'in Kraft ab 12.08.2026', null, 'entwurf', '2026-07-17'),
('lieferant', 'kernrolle', 'Lieferant', 'supplier', 'Art. 3 Abs. 1 Nr. 16 VO (EU) 2025/40', 'Jede natürliche oder juristische Person, die Verpackungen oder Verpackungsmaterial an einen Erzeuger liefert.', 'Informations- und Dokumentationspflichten gegenüber dem Erzeuger (Art. 16 Abs. 1): alle Informationen und Unterlagen zum Konformitätsnachweis (Anhang VII, Art. 5–11), auf Papier oder elektronisch, in für den Erzeuger leicht verständlicher Sprache.', 'Kein definierter Rollenbegriff im VerpackG.', 'Der Lieferant wird selbst zum Erzeuger, wenn die Kleinstunternehmen-Ausnahme (Art. 3 Abs. 1 Nr. 13 lit. b) greift. Lieferant liefert AN Erzeuger; der Vertreiber (Nr. 18) stellt auf dem Markt bereit.', 'Verpackungshersteller/Converter, deren Kunde die Verpackung unter eigener Marke fertigen lässt, sind Lieferant (nicht Erzeuger) – außer Kleinstunternehmen-Fall.', 'Als ''Vorvertreiber'' unbefüllter Serviceverpackungen möglicher Adressat der übertragenen Systembeteiligungspflicht (§ 7 Abs. 2 VerpackDG).', 'Leitfaden C(2026)3702, Abschn. 2 (Kleinstunternehmen-Konstellationen).', 'in Kraft ab 12.08.2026', null, 'entwurf', '2026-07-17'),
('importeur', 'kernrolle', 'Importeur', 'importer', 'Art. 3 Abs. 1 Nr. 17 VO (EU) 2025/40', 'Jede in der Union ansässige natürliche oder juristische Person, die Verpackungen aus einem Drittland in Verkehr bringt.', 'Pflichten nach Art. 18: nur konforme Verpackungen in Verkehr bringen; Angabe von Name/Handelsname bzw. Marke und Postanschrift auf der Verpackung (mit Ausnahmen); Dokumentation für Behörden bereithalten; Mitwirkung bei Marktüberwachung.', 'VerpackG: keine eigene Rolle – der Importeur GALT als Hersteller (§ 3 Abs. 14 VerpackG). In der PPWR ist er eigene Akteursart mit eigenen Pflichten und kann ZUSÄTZLICH Hersteller (Nr. 15) und/oder Erzeuger (Art. 21) sein.', 'Nur Drittlandsbezug (''in Verkehr bringen'' = erstmalige Bereitstellung auf dem UNIONSmarkt, Nr. 10). Innergemeinschaftlicher Bezug macht nicht zum Importeur (dort greift ggf. Hersteller-Tatbestand lit. b als erste Bereitstellung im Inland). ''Ansässig'' erfordert eigene Rechtspersönlichkeit in der EU; eine unselbstständige Zweigniederlassung (branch) genügt NICHT – Drittlandshersteller brauchen Tochtergesellschaft oder Bevollmächtigten.', '(1) ''EU-Import'' vs. Drittlandsimport. (2) Zweigniederlassung/Umsatzsteuer-Registrierung ≠ Niederlassung. (3) Eigenmarken-Importeur wird via Art. 21 zum Erzeuger.', 'Als Hersteller i. S. d. Art. 3 Abs. 1 Nr. 15: Registrierung § 6, Systembeteiligung § 7 VerpackDG.', 'Leitfaden C(2026)3702, Abschn. 4 (Branch-Frage, harmonisierter Importeurbegriff, keine strengeren nationalen Anknüpfungen zulässig).', 'in Kraft ab 12.08.2026', null, 'entwurf', '2026-07-17'),
('vertreiber', 'kernrolle', 'Vertreiber', 'distributor', 'Art. 3 Abs. 1 Nr. 18 VO (EU) 2025/40', 'Jede natürliche oder juristische Person in der Lieferkette, die Verpackungen auf dem Markt bereitstellt, mit Ausnahme des Erzeugers oder des Importeurs.', 'Sorgfaltspflichten nach Art. 19 vor der Bereitstellung: u. a. Vergewisserung über Kennzeichnung und Registereintrag des Herstellers (Art. 44); keine Bereitstellung bei Zweifeln an der Konformität; Mitwirkung bei Marktüberwachung.', 'VerpackG § 3 Abs. 12: Vertreiber = wer Verpackungen gewerbsmäßig in Verkehr bringt, unabhängig von der Handelsstufe – inhaltlich ähnlich. (Alt-Recht redaktionell verifizieren.)', 'Negativabgrenzung zu Erzeuger und Importeur. Kann zusätzlich Hersteller (Nr. 15, z. B. als Erstbereitsteller im Inland nach Bezug aus anderem Mitgliedstaat) und via Art. 21 Erzeuger werden (Eigenmarke/Modifikation).', 'Großhändler, der Ware aus anderem EU-Staat bezieht und in DE erstmals bereitstellt, ist Vertreiber UND Hersteller (EPR) – häufig übersehen.', '§ 3 Abs. 17/18 VerpackDG definieren zusätzlich national ''Erstinverkehrbringer'' und ''Inverkehrbringer'' (für §§ 12 ff.); Rücknahmepflichten §§ 39 ff.', 'Leitfaden C(2026)3702, Abschn. 3 und 4.', 'in Kraft ab 12.08.2026', null, 'entwurf', '2026-07-17'),
('bevollmaechtigter', 'kernrolle', 'Bevollmächtigter', 'authorised representative', 'Art. 3 Abs. 1 Nr. 19 VO (EU) 2025/40', 'Jede in der Union ansässige natürliche oder juristische Person, die vom ERZEUGER schriftlich beauftragt wurde, in dessen Namen bestimmte Aufgaben zur Erfüllung der Erzeugerpflichten wahrzunehmen.', 'Aufgaben nach Art. 17 auf Basis des schriftlichen Mandats (insb. Bereithalten von Konformitätserklärung/technischer Dokumentation, Behördenkooperation). Kann die EU-Konformitätserklärung erstellen; die rechtliche Verantwortung bleibt beim Erzeuger.', 'Kein Pendant (der Bevollmächtigte des § 35 VerpackG betraf die Herstellerpflichten, entspricht also dem EHV-Bevollmächtigten Nr. 20; Alt-Recht redaktionell verifizieren).', 'STRIKT zu trennen vom ''Bevollmächtigten für die erweiterte Herstellerverantwortung'' (Nr. 20): Nr. 19 = Konformitätsschiene (Erzeuger), Nr. 20 = EPR-Schiene (Hersteller). Zwei verschiedene Institute mit verschiedenen Auftraggebern.', 'Die beiden Bevollmächtigten-Typen werden in der Praxis ständig verwechselt; UI muss beide getrennt ausweisen.', '—', 'Leitfaden C(2026)3702, Abschn. 2 (Rolle bei Konformitätserklärung).', 'in Kraft ab 12.08.2026', null, 'entwurf', '2026-07-17'),
('bevollmaechtigter_ehv', 'kernrolle', 'Bevollmächtigter für die erweiterte Herstellerverantwortung', 'authorised representative for extended producer responsibility', 'Art. 3 Abs. 1 Nr. 20 i. V. m. Art. 45 Abs. 3 VO (EU) 2025/40', 'Person mit Niederlassung im Ziel-Mitgliedstaat (in dem der Hersteller erstmals bereitstellt bzw. auspackt), benannt vom HERSTELLER gemäß Art. 8a Abs. 5 UAbs. 3 der Richtlinie 2008/98/EG, zur Erfüllung von dessen Pflichten nach Kapitel VIII PPWR.', 'Übernimmt die EPR-Pflichten des ausländischen Herstellers im Zielstaat. DE-Ausgestaltung: § 5 Abs. 2–6 VerpackDG.', 'Entspricht funktional dem Bevollmächtigten nach § 35 VerpackG (Alt-Recht redaktionell verifizieren); jetzt unionsrechtlich verankert.', 'Pflichtfälle nach § 5 Abs. 2 VerpackDG: Hersteller nach Art. 45 Abs. 3 Satz 1 (Sitz in anderem Mitgliedstaat) und – Ausübung der Mitgliedstaaten-Option – nach Art. 45 Abs. 3 Satz 2 (Sitz im Drittland) ohne Niederlassung im Bundesgebiet müssen VOR der ersten Bereitstellung beauftragen bzw. benennen. Nur EIN Bevollmächtigter je Hersteller (§ 5 Abs. 4 Satz 1); schriftliche Vollmacht in deutscher Sprache (§ 5 Abs. 4 Satz 2); Benennung gegenüber der ZSVR im Rahmen der Registrierung (Bestätigungserfordernis); der Bevollmächtigte gilt hinsichtlich der wahrzunehmenden Pflichten als Hersteller und handelt im eigenen Namen (§ 5 Abs. 3). Die Registrierung nach § 6 und Datenmeldungen nach § 9 sind NICHT auf beauftragte Dritte delegierbar (§ 5 Abs. 1 Satz 2); die Registrierung ist auch vom EHV-Bevollmächtigten ausgenommen (§ 5 Abs. 2).', 'Verwechslung mit Nr. 19 (s. dort); zudem Abgrenzung zum ''beauftragten Dritten'' nach § 5 Abs. 1 VerpackDG (allgemeine Pflichtenübertragung ohne Bevollmächtigten-Status).', '§ 5 Abs. 2 (Pflichtfälle Art. 45 Abs. 3 Satz 1 und Satz 2), Abs. 3 (gilt als Hersteller, handelt im eigenen Namen), Abs. 4 (nur ein Bevollmächtigter; schriftliche Vollmacht in deutscher Sprache), Abs. 5 (Benennung ggü. ZSVR mit Bestätigung), Abs. 6 (Beendigung); § 6 Abs. 1 Satz 3, Abs. 2 Satz 1 Nr. 2 und 4 VerpackDG (BGBl. 2026 I Nr. 207).', 'Leitfaden C(2026)3702, Abschn. 4 (Drittlandshersteller: Tochter ODER Bevollmächtigter, wenn Mitgliedstaat dies vorschreibt – DE schreibt es vor).', 'in Kraft ab 12.08.2026', null, 'entwurf', '2026-07-17'),
('endvertreiber', 'kernrolle', 'Endvertreiber', 'final distributor', 'Art. 3 Abs. 1 Nr. 21 VO (EU) 2025/40', 'Die natürliche oder juristische Person in der Lieferkette, die verpackte Produkte – einschließlich durch Wiederverwendung – oder Produkte, die in Form einer Wiederbefüllung erworben werden können, an den Endabnehmer liefert.', 'Adressat der endkundennahen Pflichten: u. a. Mehrweg-Angebotsquote für Getränke (Art. 29 Abs. 6: mind. 10 % ab 2030), Wiederbefüllung/Mitbring-Behälter (Art. 32/33), Rücknahme- und Pfandpflichten national (§§ 39 ff., 46 VerpackDG), Annahme pfandpflichtiger Verpackungen (Anhang X).', 'Entspricht dem ''Letztvertreiber'' des VerpackG (§ 3 Abs. 13; Alt-Recht redaktionell verifizieren).', 'Immer Zusatzrolle zum Vertreiber-Status; maßgeblich ist die Lieferung an den ENDABNEHMER (Nr. 23: Verbraucher ODER beruflicher Endabnehmer, der das Produkt nicht in gelieferter Form weiter bereitstellt). Im Fernabsatz ist Endvertreiber, wer über die Website bereitstellt.', 'B2B-Kunde kann Endabnehmer sein (beruflicher Endabnehmer) – Endvertreiber-Pflichten greifen dann auch im B2B.', '§§ 39 ff. (Rücknahme/Verwertung), § 44 (Mehrweg-Förderung), § 46 (Pfand), § 47 (Hinweispflichten), § 60/61 (Mehrwegalternative, Erleichterungen kleine Unternehmen).', 'Leitfaden C(2026)3702, Abschn. 22/23 (Endvertreiber bei Mehrwegquote, HORECA, Fernabsatz).', 'in Kraft ab 12.08.2026', null, 'entwurf', '2026-07-17'),
('fulfillment_dienstleister', 'kernrolle', 'Fulfillment-Dienstleister', 'fulfilment service provider', 'Art. 3 Abs. 1 UAbs. 3 VO (EU) 2025/40 i. V. m. Art. 3 Nr. 11 VO (EU) 2019/1020', 'Per Verweis definiert: natürliche oder juristische Person, die im Rahmen einer Geschäftstätigkeit mindestens zwei der folgenden Dienstleistungen anbietet: Lagerhaltung, Verpackung, Adressierung und Versand von Produkten, an denen sie kein Eigentumsrecht hat – ausgenommen Postdienste, Paketzustelldienste und sonstige Post-/Frachtdienste (Wortlaut gegen VO (EU) 2019/1020 pinnen).', 'Pflichten nach Art. 20 (Prüf-/Mitwirkungspflichten zur Verhinderung von EPR-Trittbrettfahrern, vgl. ErwG 133); kein Hersteller allein durch die Dienstleistung, kann aber bei Umpacken von Drittlandsware als Auspacker (Nr. 15 lit. e) oder für Transportverpackungen zum Hersteller werden (ErwG 123).', 'Kein Pendant im VerpackG.', 'Kein Eigentum an der Ware; reine Transport-/Postdienstleister sind ausgenommen. Abgrenzung zum Vertreiber: der Fulfillment-Dienstleister stellt nicht selbst auf dem Markt bereit.', 'Fulfillment-Center, das Drittlandsware umpackt und die Original-Transportverpackung entsorgt, wird für diese Verpackung Hersteller – zentraler Beratungsfall E-Commerce.', '§ 13 Abs. 4 VerpackDG: Tätigkeitsverbot bei nicht registrierten Herstellern; verweist auf Art. 3 Nr. 11 VO (EU) 2019/1020 „in der Fassung vom 12. August 2026“; automatisierter Registerdatenabgleich der ZSVR. Bußgeldbewehrte Mitwirkungspflichten (§ 66 VerpackDG i. V. m. Art. 20).', 'Leitfaden C(2026)3702, Abschn. 3 (Logistiker als Hersteller der Transportverpackung).', 'in Kraft ab 12.08.2026', '!', 'entwurf', '2026-07-17'),
('hb_bereitstellung_markt', 'hilfsbegriff', 'Bereitstellung auf dem Markt', 'making available on the market', 'Art. 3 Abs. 1 Nr. 9 VO (EU) 2025/40', 'Jede entgeltliche oder unentgeltliche Abgabe befüllter oder unbefüllter Verpackungen zum Vertrieb, Verbrauch oder zur Verwendung auf dem Unionsmarkt im Rahmen einer Geschäftstätigkeit.', 'Basisbegriff aller Rollen-Tatbestände.', 'Vgl. ''Inverkehrbringen'' § 3 Abs. 9 VerpackG (abweichend definiert).', 'Bereitstellung erfordert keine physische Übergabe; auch das Angebot, das zur Lieferung führen kann, genügt (ErwG 122). Bei Online-Plattformen gilt bereits das erstmalige Anbieten.', '''Bereitstellung im Hoheitsgebiet des Mitgliedstaats'' (Nr. 11) ist der EPR-Anker; ''Inverkehrbringen'' (Nr. 10) = ERSTE Bereitstellung auf dem Unionsmarkt (Konformitätsanker).', '§ 3 Abs. 3 VerpackDG: ''Bereitstellung im Bundesgebiet'' = Nr. 11 bezogen auf Deutschland.', 'Leitfaden C(2026)3702, Abschn. 5 (Zeitpunkt des Inverkehrbringens; Import: Überlassung zum zollrechtlich freien Verkehr).', 'in Kraft ab 12.08.2026', null, 'entwurf', '2026-07-17'),
('hb_endabnehmer', 'hilfsbegriff', 'Endabnehmer', 'end user', 'Art. 3 Abs. 1 Nr. 23 VO (EU) 2025/40', 'Natürliche oder juristische Person mit Wohnsitz/Niederlassung in der Union, der ein Produkt als Verbraucher oder beruflicher Endabnehmer bereitgestellt wird und die es in der gelieferten Form nicht erneut auf dem Markt bereitstellt.', 'Schaltbegriff für Hersteller lit. c/d (Direktlieferung) und lit. e (Auspacker ''ohne Endabnehmer zu sein'') sowie für den Endvertreiber.', 'Vgl. ''Endverbraucher'' § 3 Abs. 11 VerpackG (Alt-Recht redaktionell verifizieren).', 'Beruflicher Endabnehmer: verwendet das Produkt selbst (z. B. Abfüller ist Endabnehmer der zugekauften LEEREN Folien/Paletten aus anderem Mitgliedstaat? NEIN – EUNR: der Befüller ist für Verpackungsmaterial gerade KEIN Endabnehmer; Klärung mit Cattwyk).', 'Endabnehmer des PRODUKTS vs. Nutzer der VERPACKUNG – bei lit. c geht es um den Endabnehmer des Produkts (EUNR-Papier).', '—', 'Leitfaden C(2026)3702, Abschn. 3; EUNR-Papier 06/2026 (Sekundärquelle).', 'in Kraft ab 12.08.2026', '!', 'entwurf', '2026-07-17'),
('hb_erstinverkehrbringer_de', 'hilfsbegriff', 'Erstinverkehrbringer / Inverkehrbringer (national)', '—', '§ 3 Abs. 17 und 18 VerpackDG (BGBl. 2026 I Nr. 207; national ergänzend)', 'Erstinverkehrbringer: wer Verpackungen erstmals gewerbsmäßig im Bundesgebiet bereitstellt. Inverkehrbringer: wer Verpackungen unabhängig von Vertriebsmethode oder Handelsstufe im Bundesgebiet bereitstellt.', 'Nationale Anknüpfungsbegriffe für Bereitstellungsbeschränkungen und Pfand (§§ 12 ff., 46 VerpackDG); NICHT mit den PPWR-Rollen verwechseln.', 'Fortführung der VerpackG-Systematik auf neuer Begriffsbasis.', 'Rein nationale Begriffe neben dem PPWR-Rollenkanon.', 'Darf im UI nicht als eigene ''Rolle'' erscheinen, sondern als Pflichtenanker einzelner Anforderungen.', '§ 3 Abs. 17, 18 VerpackDG.', '—', 'in Kraft ab 12.08.2026', null, 'entwurf', '2026-07-17');

insert into rollen_regeln (regel_id, block, prioritaet, wenn_bedingung, dann_rollen, geltungsebene, fundstelle_primaer, fundstelle_sekundaer, erlaeuterung, input_variablen, flag) values
('A1', 'erzeuger', 10, 'verpackungsart IN (verkauf, um) UND taetigkeit ENTHÄLT befuellt_versiegelt UND bringt_in_verkehr = ja UND NOT regel A3', 'erzeuger', 'EU-weit (einmal je Verpackung)', 'Art. 3 Abs. 1 Nr. 13 VO (EU) 2025/40', 'Leitfaden C(2026)3702, Abschn. 2 (Abfüller-Regel)', 'Bei Verkaufs- und Umverpackungen ist Erzeuger regelmäßig, wer die finalen Verarbeitungsschritte (Zuschneiden, Befüllen, Versiegeln) vornimmt und die Verpackung bzw. das verpackte Produkt erstmals auf dem Unionsmarkt bereitstellt – häufig zugleich Markeninhaber des Produkts.', 'verpackungsart; taetigkeit; bringt_in_verkehr', null),
('A2', 'erzeuger', 20, 'marke_auf_verpackung = eigene UND taetigkeit ENTHÄLT (entwickeln_lassen ODER herstellen_lassen) UND NOT regel A3', 'erzeuger', 'EU-weit', 'Art. 3 Abs. 1 Nr. 13 lit. a VO (EU) 2025/40', 'Leitfaden C(2026)3702, Abschn. 2 (Markenkriterium)', 'Wer Verpackung oder verpacktes Produkt unter eigenem Namen/eigener Marke entwickeln oder herstellen lässt, ist Erzeuger – unabhängig von physischer Produktion und unabhängig davon, ob weitere Marken sichtbar sind (Private-Label-Fall).', 'marke_auf_verpackung; taetigkeit', null),
('A3', 'erzeuger', 5, 'regel A2 erfüllt UND unternehmensgroesse = kleinstunternehmen (Stand 11.02.2025) UND verpackungslieferant_sitz = gleicher_mitgliedstaat', 'erzeuger_ist_lieferant (eigene Rolle: lieferant_als_erzeuger; Markeninhaber entlastet)', 'EU-weit', 'Art. 3 Abs. 1 Nr. 13 lit. b VO (EU) 2025/40', 'Leitfaden C(2026)3702, Abschn. 2 (gilt unabhängig davon, ob der Lieferant selbst Kleinstunternehmen ist; Verbund-/Franchise-Berechnung nach Art. 3 Empf. 2003/361/EG)', 'Kleinstunternehmen: < 10 Beschäftigte UND Jahresumsatz ODER Bilanzsumme ≤ 2 Mio. EUR (Empfehlung 2003/361/EG in der am 11.02.2025 geltenden Fassung). Beide Bedingungen (Größe + Lieferant im selben Mitgliedstaat) müssen kumulativ vorliegen, sonst bleibt der Markeninhaber Erzeuger.', 'unternehmensgroesse; verpackungslieferant_sitz', '!'),
('A4', 'erzeuger', 30, 'verpackungsart IN (transport, service, primaerproduktion) UND marke_auf_verpackung != nutzer_marke UND taetigkeit ENTHÄLT stellt_verpackung_physisch_her', 'erzeuger', 'EU-weit', 'Art. 3 Abs. 1 Nr. 13 VO (EU) 2025/40', 'Leitfaden C(2026)3702, Abschn. 2 (bei Transport-/Service-/Primärproduktionsverpackung regelmäßig der Verpackungshersteller; bei Branding durch den Nutzer dieser; ohne Marke: wer bestellt und Designspezifikationen festlegt)', 'Für leere Gebrauchsverpackungen ist der physische Hersteller Erzeuger, außer die Verpackung trägt die Marke des Verwenders. Unbrandete Sonderanfertigungen: Besteller mit Design-Hoheit.', 'verpackungsart; marke_auf_verpackung; taetigkeit', null),
('A5', 'erzeuger', 15, 'rolle_basis IN (importeur, vertreiber) UND (bringt_unter_eigenem_namen_in_verkehr = ja ODER veraendert_verpackung_konformitaetsrelevant = ja)', 'erzeuger (Zurechnung; zusätzlich zur Basisrolle)', 'EU-weit', 'Art. 21 VO (EU) 2025/40', 'Leitfaden C(2026)3702, Abschn. 2', 'Importeure und Vertreiber gelten als Erzeuger, wenn sie Verpackungen unter eigenem Namen/eigener Marke in Verkehr bringen oder bereits in Verkehr gebrachte Verpackungen so verändern, dass die Konformität berührt sein kann. Übernahme sämtlicher Erzeugerpflichten.', 'rolle_basis; bringt_unter_eigenem_namen_in_verkehr; veraendert_verpackung_konformitaetsrelevant', null),
('B1', 'hersteller', 10, 'verpackungsart IN (transport, service, primaerproduktion) UND zustand = leer UND sitz = DE UND erste_bereitstellung_aus_DE_in_DE = ja', 'hersteller', 'DE (je Mitgliedstaat)', 'Art. 3 Abs. 1 Nr. 15 lit. a VO (EU) 2025/40', 'Leitfaden C(2026)3702, Abschn. 3; ErwG 122; EUNR-Papier 06/2026 (Sekundärquelle: Lieferkette beginnt bei der fertigen leeren Verpackung; bei Folien u. ä. erst mit der Befüllung)', 'Für Transport-, Service- und Primärproduktionsverpackungen wird der Hersteller anhand der LEEREN Verpackung bestimmt (Entlastung kleiner Befüller). Erst-Bereitsteller in DE = Hersteller.', 'verpackungsart; zustand; sitz; erste_bereitstellung_aus_DE_in_DE', '!'),
('B2', 'hersteller', 20, 'verpackungsart IN (verkauf, um, sonstige_befuellt) UND sitz = DE UND erste_bereitstellung_aus_DE_in_DE = ja', 'hersteller', 'DE', 'Art. 3 Abs. 1 Nr. 15 lit. b VO (EU) 2025/40', 'Leitfaden C(2026)3702, Abschn. 3 (Verkaufsverpackung: der Befüller, der erstmals im Mitgliedstaat bereitstellt); ErwG 122; EUNR-Papier', 'Bei verpackten Produkten ist Hersteller, wer sie erstmals in DE bereitstellt: der inländische Abfüller ODER – bei Bezug verpackter Ware aus anderem Mitgliedstaat/Drittland – das erste inländische Unternehmen in der Lieferkette.', 'verpackungsart; sitz; erste_bereitstellung_aus_DE_in_DE', null),
('B3', 'hersteller', 30, 'vertriebsweg ENTHÄLT fernabsatz_direkt_an_endabnehmer_DE UND sitz IN (anderer_mitgliedstaat, drittland)', 'hersteller (in DE) + pflicht_bevollmaechtigter_ehv', 'DE', 'Art. 3 Abs. 1 Nr. 15 lit. c und d VO (EU) 2025/40; § 5 Abs. 2 VerpackDG (BGBl. 2026 I Nr. 207)', 'Leitfaden C(2026)3702, Abschn. 3 (distance seller is the producer; Plattform-Prüfpflichten); ErwG 123, 132', 'Wer aus dem Ausland direkt an Endabnehmer in DE liefert, ist Hersteller in DE. Ohne Niederlassung im Bundesgebiet: Pflicht zur Beauftragung/Benennung eines Bevollmächtigten für die erweiterte Herstellerverantwortung vor der ersten Bereitstellung (Registrierung selbst ausgenommen).', 'vertriebsweg; sitz; niederlassung_DE', '!'),
('B4', 'hersteller', 40, 'taetigkeit ENTHÄLT packt_aus UND ist_endabnehmer = nein UND kein_anderer_hersteller_nach_a_bis_d = ja', 'hersteller (Auffangtatbestand)', 'DE', 'Art. 3 Abs. 1 Nr. 15 lit. e VO (EU) 2025/40; § 6 Abs. 1 VerpackDG (Registrierung vor dem Auspacken)', 'Leitfaden C(2026)3702, Abschn. 3 (Logistikunternehmen: Umpacken von Drittlandsware macht zum Hersteller der Transportverpackung, auch ohne Eigentum); ErwG 123', 'Auspacker-Tatbestand: Wer verpackte Produkte auspackt, ohne Endabnehmer zu sein, wird Hersteller der anfallenden Verpackung, sofern kein anderer Hersteller nach lit. a–d existiert. Kernfall: Fulfillment/Logistik mit Drittlandsware. Registrierung VOR dem Auspacken.', 'taetigkeit; ist_endabnehmer', '!'),
('B5', 'hersteller', 50, 'warenstrom = export_aus_EU', 'kein_hersteller (für diese Mengen)', 'DE/EU', 'Art. 3 Abs. 1 Nr. 15 i. V. m. Art. 45 VO (EU) 2025/40 (Systematik)', 'Leitfaden C(2026)3702, Abschn. 3 (Export: kein producer, da kein Abfall in der EU erwartet; bei Weitervertrieb in anderen Mitgliedstaat: Gebührenerstattung)', 'Exportmengen lösen keine EPR in DE aus. Wird nach Gebührenzahlung in DE erstmals in einem anderen Mitgliedstaat bereitgestellt, sind die Beiträge zu erstatten; die Pflicht entsteht dort neu.', 'warenstrom', '!'),
('B6', 'hersteller', 60, 'rolle = hersteller UND verpackung IN systembeteiligungspflichtig (§ 3 Abs. 6 VerpackDG)', 'rechtsfolgen_DE: registrierung_zsvr + systembeteiligung + datenmeldung', 'DE', '§§ 6, 7, 9, 10 VerpackDG; Art. 44, 45 VO (EU) 2025/40', '§ 68 VerpackDG (Übergang, final: LUCID-Registrierungen gelten fort, Abs. 2 Satz 1; Änderungsmitteilungen bis 12.11.2026, Abs. 2 Satz 2; erstmals Verpflichtete bis 12.09.2026, Abs. 2 Satz 3; Alt-Systembeteiligungen längstens bis 31.12.2026, Abs. 1); § 68 Abs. 17: Bußgeldtatbestände für PPWR-Verstöße (§ 66 Abs. 2) erst ab 12.02.2027 anwendbar', 'Rechtsfolgen-Kaskade in DE: Registrierung bei der ZSVR vor erstmaliger Bereitstellung bzw. vor dem Auspacken (§ 6 Abs. 1); Systembeteiligung mit Materialart/Masse (§ 7 Abs. 1); bei Serviceverpackungen Übertragungsmöglichkeit auf Vorvertreiber (§ 7 Abs. 2 – Auslegungsfrage, s. Review); Datenmeldung § 9; ggf. Vollständigkeitserklärung § 10.', 'rolle; verpackungskategorie_systembeteiligung', '!'),
('C1', 'weitere', 10, 'taetigkeit ENTHÄLT importiert_drittland UND bringt_in_verkehr = ja UND eu_rechtspersoenlichkeit = ja', 'importeur', 'EU-weit', 'Art. 3 Abs. 1 Nr. 17; Art. 18 VO (EU) 2025/40', 'Leitfaden C(2026)3702, Abschn. 4 (Zweigniederlassung genügt nicht; harmonisierter Begriff)', 'Importeur ist nur, wer mit eigener EU-Rechtspersönlichkeit Drittlandsverpackungen erstmals auf dem Unionsmarkt bereitstellt. Zweigniederlassung/USt-Registrierung reicht nicht: dann Tochtergesellschaft oder Bevollmächtigter erforderlich.', 'taetigkeit; eu_rechtspersoenlichkeit', '!'),
('C2', 'weitere', 20, 'taetigkeit ENTHÄLT stellt_bereit UND rolle != erzeuger UND rolle != importeur', 'vertreiber', 'EU-weit', 'Art. 3 Abs. 1 Nr. 18; Art. 19 VO (EU) 2025/40', '—', 'Auffangrolle der Lieferkette mit Sorgfaltspflichten (u. a. Prüfung Registereintrag des Herstellers, Art. 44).', 'taetigkeit; rolle', null),
('C3', 'weitere', 30, 'taetigkeit ENTHÄLT liefert_an_endabnehmer', 'endvertreiber (zusätzlich)', 'EU-weit + DE-Pflichten', 'Art. 3 Abs. 1 Nr. 21 VO (EU) 2025/40; §§ 39 ff., 46 VerpackDG', 'Leitfaden C(2026)3702, Abschn. 22/23', 'Zusatzrolle bei Lieferung an Endabnehmer (auch beruflicher Endabnehmer, auch via Website). Löst endkundennahe Pflichten aus (Mehrwegangebot, Rücknahme, Pfand).', 'taetigkeit', null),
('C4', 'weitere', 40, 'taetigkeit ENTHÄLT lagert_und_versendet_fuer_dritte UND eigentum_an_ware = nein UND dienstleistungen >= 2 aus (lagerhaltung, verpackung, adressierung, versand)', 'fulfillment_dienstleister', 'EU-weit', 'Art. 3 Abs. 1 UAbs. 3 VO (EU) 2025/40 i. V. m. Art. 3 Nr. 11 VO (EU) 2019/1020; Art. 20 VO (EU) 2025/40', 'ErwG 133; Leitfaden C(2026)3702, Abschn. 3', 'Mindestens zwei der vier Dienstleistungen ohne Eigentum an der Ware; Post-/Paket-/Frachtdienste ausgenommen. Bei Umpacken von Drittlandsware zusätzlich Prüfung Regel B4.', 'taetigkeit; eigentum_an_ware; dienstleistungen', '!'),
('C5', 'weitere', 50, 'taetigkeit ENTHÄLT liefert_verpackungen_oder_material_an_erzeuger', 'lieferant', 'EU-weit', 'Art. 3 Abs. 1 Nr. 16; Art. 16 VO (EU) 2025/40', 'Leitfaden C(2026)3702, Abschn. 2 (Kleinstunternehmen-Ausnahme: Lieferant kann Erzeuger werden, Regel A3)', 'Informationspflichten gegenüber dem Erzeuger (Anhang VII); bei Serviceverpackungen zugleich potenzieller Vorvertreiber i. S. d. § 7 Abs. 2 VerpackDG.', 'taetigkeit', null),
('C6', 'weitere', 60, 'rolle = hersteller UND sitz IN (anderer_mitgliedstaat, drittland) UND niederlassung_DE = nein', 'pflicht: bevollmaechtigter_ehv beauftragen/benennen (vor erster Bereitstellung)', 'DE', 'Art. 45 Abs. 3 Satz 1 und 2 VO (EU) 2025/40; § 5 Abs. 2–6 VerpackDG (BGBl. 2026 I Nr. 207)', 'Leitfaden C(2026)3702, Abschn. 4', 'DE hat die Drittlands-Option des Art. 45 Abs. 3 Satz 2 ausgeübt (§ 5 Abs. 2 Satz 2 VerpackDG). Nur ein Bevollmächtigter je Hersteller; schriftliche Vollmacht auf Deutsch; Benennung gegenüber ZSVR mit Bestätigung; Registrierung nicht delegierbar.', 'rolle; sitz; niederlassung_DE', null),
('Z1', 'output', 1, 'IMMER', 'rollen_set_je_produktlinie (Mehrfachrollen möglich; keine pauschale Firmenrolle)', '—', 'Systematik Art. 3 Abs. 1 Nr. 12–21 VO (EU) 2025/40', 'Leitfaden C(2026)3702, Abschn. 2/3 (Tabelle Manufacturer vs. Producer)', 'Output-Prinzip der Engine: Jede Produktlinie erhält ein Rollen-SET mit Herleitung (angewandte Regeln + Fundstellen). Typische Doppelrollen: Marken-Abfüller = Erzeuger + Hersteller; Eigenmarken-Importeur = Importeur + Erzeuger (Art. 21) + ggf. Hersteller; Händler mit Endkundengeschäft = Vertreiber + Endvertreiber + ggf. Hersteller (lit. b bei EU-Bezug).', 'alle', null);

insert into wizard_fragen (frage_id, reihenfolge, ebene, frage_text, antwort_typ, antwort_optionen, ziel_variable, bedingung_anzeige, gespeiste_regeln, hinweis_ui) values
('F01', 1, 'unternehmen', 'Wo hat Ihr Unternehmen seinen Sitz?', 'single_select', 'Deutschland | anderer EU-/EWR-Mitgliedstaat | Drittland (außerhalb EU/EWR)', 'sitz', 'immer', 'B1,B2,B3,C1,C6', null),
('F02', 2, 'unternehmen', 'Hat Ihr Unternehmen eine Niederlassung mit eigener Rechtspersönlichkeit in Deutschland (z. B. GmbH, keine bloße Zweigniederlassung)?', 'single_select', 'ja | nein', 'niederlassung_DE', 'sitz != Deutschland', 'B3,C1,C6', 'Hinweis einblenden: Eine unselbstständige Zweigniederlassung oder eine reine Umsatzsteuer-Registrierung genügt nicht (Leitfaden C(2026)3702, Abschn. 4).'),
('F03', 3, 'unternehmen', 'Wie groß ist Ihr Unternehmen (einschließlich verbundener Unternehmen und Partnerunternehmen)?', 'single_select', 'Kleinstunternehmen: unter 10 Beschäftigte UND Jahresumsatz oder Bilanzsumme bis 2 Mio. EUR | größer', 'unternehmensgroesse', 'immer', 'A3', 'Berechnung nach Empfehlung 2003/361/EG in der am 11.02.2025 geltenden Fassung; verbundene Unternehmen (z. B. Franchise mit ≥ 25 % Beteiligung) sind einzurechnen.'),
('F04', 4, 'produktlinie', 'Legen Sie Ihre Produktlinien an. Eine Produktlinie ist eine Gruppe von Produkten mit gleichartiger Verpackungssituation (z. B. ''Feinkost im Glas'', ''Ersatzteile im Versandkarton'').', 'freitext_liste', '—', 'produktlinien', 'immer', 'alle', 'Alle Folgefragen werden JE PRODUKTLINIE gestellt – die Engine gibt nie eine pauschale Firmenrolle aus.'),
('F05', 5, 'produktlinie', 'Welche Verpackungsarten setzen Sie in dieser Produktlinie ein?', 'multi_select', 'Verkaufsverpackung (Art. 3 Abs. 1 Nr. 5) | Umverpackung (Nr. 6) | Transportverpackung (Nr. 7) | Verpackung für den elektronischen Handel (Nr. 8) | Serviceverpackung (Nr. 1 lit. d) | Primärproduktionsverpackung (Nr. 4)', 'verpackungsart', 'immer', 'A1,A4,B1,B2', null),
('F06', 6, 'produktlinie', 'Was trifft auf Ihre Tätigkeiten in dieser Produktlinie zu? (Mehrfachauswahl – bitte alle zutreffenden Tätigkeiten ankreuzen)', 'multi_select', 'Wir stellen Verpackungen selbst physisch her | Wir befüllen/versiegeln Verpackungen mit unseren Produkten | Wir lassen Verpackungen oder verpackte Produkte unter unserem Namen/unserer Marke entwickeln oder herstellen | Wir kaufen fertig verpackte Ware und verkaufen sie weiter | Wir führen Verpackungen oder verpackte Ware aus einem Drittland ein | Wir verkaufen an Endkunden (Verbraucher oder gewerbliche Endnutzer) | Wir packen angelieferte Ware aus und verpacken sie neu bzw. entsorgen die Anlieferverpackung | Wir lagern und versenden Ware für Dritte (Fulfillment) | Wir liefern leere Verpackungen oder Verpackungsmaterial an Befüller', 'taetigkeit', 'immer', 'A1,A2,A4,B2,B4,C1,C2,C3,C4,C5', 'Tätigkeitsabfrage statt Selbsteinschätzung – die Rollenableitung übernimmt die Engine.'),
('F07', 7, 'produktlinie', 'Trägt die Verpackung (nicht das Produkt) einen Namen oder eine Marke – und wenn ja, wessen?', 'single_select', 'unsere eigene Marke / unser Name | Marke eines anderen Unternehmens | keine Marke auf der Verpackung', 'marke_auf_verpackung', 'immer', 'A2,A4,A5', null),
('F08', 8, 'produktlinie', 'Woher beziehen Sie die (leeren) Verpackungen dieser Produktlinie?', 'single_select', 'vom Lieferanten in Deutschland | vom Lieferanten in einem anderen EU-Mitgliedstaat | aus einem Drittland | wir stellen sie selbst her', 'verpackungslieferant_sitz', 'taetigkeit ENTHÄLT (befuellt ODER herstellen_lassen)', 'A3,C1', null),
('F09', 9, 'produktlinie', 'Wer stellt die Verpackung bzw. das verpackte Produkt in Deutschland ERSTMALS bereit – Sie oder ein Unternehmen vor Ihnen in der Lieferkette?', 'single_select', 'wir sind die Ersten in Deutschland (z. B. wir befüllen hier ODER beziehen aus dem Ausland und liefern hier) | ein deutsches Unternehmen vor uns (wir kaufen im Inland zu) | unklar', 'erste_bereitstellung_aus_DE_in_DE', 'sitz = Deutschland', 'B1,B2', 'Bei ''unklar'' Eskalation: Ebene-3-Disclaimer + Hinweis auf Cattwyk-Erstgespräch.'),
('F10', 10, 'produktlinie', 'Über welche Wege vertreiben Sie diese Produktlinie?', 'multi_select', 'stationär / B2B in Deutschland | Online-Verkauf an Endkunden in Deutschland | Online-Verkauf an Endkunden in anderen EU-Staaten | Export in Drittländer | Verkauf an Wiederverkäufer im EU-Ausland', 'vertriebsweg', 'immer', 'B3,B5,C3', null),
('F11', 11, 'produktlinie', 'Falls Sie Ware auspacken (siehe Tätigkeiten): Verwenden Sie die ausgepackten Produkte selbst, oder verkaufen/versenden Sie sie weiter?', 'single_select', 'wir verwenden sie selbst (Endabnehmer) | wir verkaufen oder versenden sie weiter', 'ist_endabnehmer', 'taetigkeit ENTHÄLT packt_aus', 'B4', null),
('F12', 12, 'produktlinie', 'Falls Fulfillment für Dritte: Welche Leistungen erbringen Sie, und gehört Ihnen die Ware?', 'multi_select', 'Lagerhaltung | Verpackung | Adressierung | Versand | die Ware gehört uns (Eigentum)', 'dienstleistungen; eigentum_an_ware', 'taetigkeit ENTHÄLT lagert_und_versendet_fuer_dritte', 'C4', null),
('F13', 13, 'produktlinie', 'Hat der Lebensmittelkontakt für diese Produktlinie Relevanz (Verpackung kommt mit Lebensmitteln in Berührung)?', 'single_select', 'ja | nein', 'lebensmittelkontakt', 'immer', '— (speist Schicht 2: PFAS Art. 5 Abs. 5 u. a.)', 'Keine Rollenfrage; wird für die Anforderungs-Matrix (Schicht 2) erhoben.');